332: /* Returns number of expired fields. */
333: static uint64_t listpackExExpireDryRun(const robj *o) {
334:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
335: 
336:     uint64_t expired = 0;
337:     unsigned char *fptr;
338:     listpackEx *lpt = o->ptr;
339: 
340:     fptr = lpFirst(lpt->lp);
341:     while (fptr != NULL) {
342:         long long val;
343: 
344:         fptr = lpNext(lpt->lp, fptr);
345:         serverAssert(fptr);
346:         fptr = lpNext(lpt->lp, fptr);
347:         serverAssert(fptr && lpGetIntegerValue(fptr, &val));
348: 
349:         if (!hashTypeIsExpired(o, val))
350:             break;
351: 
352:         expired++;
353:         fptr = lpNext(lpt->lp, fptr);
354:     }
355: 
356:     return expired;
357: }
