359: /* Returns the expiration time of the item with the nearest expiration. */
360: static uint64_t listpackExGetMinExpire(robj *o) {
361:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
362: 
363:     long long expireAt;
364:     unsigned char *fptr;
365:     listpackEx *lpt = o->ptr;
366: 
367:     /* As fields are ordered by expire time, first field will have the smallest
368:      * expiry time. Third element is the expiry time of the first field */
369:     fptr = lpSeek(lpt->lp, 2);
370:     if (fptr != NULL) {
371:         serverAssert(lpGetIntegerValue(fptr, &expireAt));
372: 
373:         /* Check if this is a non-volatile field. */
374:         if (expireAt != HASH_LP_NO_TTL)
375:             return expireAt;
376:     }
377: 
378:     return EB_EXPIRE_TIME_INVALID;
379: }
380: 
381: /* Walk over fields and delete the expired ones. */
382: void listpackExExpire(robj *o, ExpireInfo *info) {
383:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
384:     uint64_t min = EB_EXPIRE_TIME_INVALID;
385:     unsigned char *ptr, *field;
386:     listpackEx *lpt = o->ptr;
387: 
388:     ptr = lpFirst(lpt->lp);
389:     while (ptr != NULL && (info->itemsExpired < info->maxToExpire)) {
390:         long long val;
391: 
392:         field = ptr;
393:         ptr = lpNext(lpt->lp, ptr);
394:         serverAssert(ptr);
395:         ptr = lpNext(lpt->lp, ptr);
396:         serverAssert(ptr && lpGetIntegerValue(ptr, &val));
397: 
398:         /* Fields are ordered by expiry time. If we reached to a non-expired
399:          * field or a non-volatile field, we know rest is not yet expired. */
400:         if (val == HASH_LP_NO_TTL || (uint64_t) val > info->now)
401:             break;
402: 
403:         lpt->lp = lpDeleteRangeWithEntry(lpt->lp, &field, 3);
404:         ptr = field;
405:         info->itemsExpired++;
406:     }
407: 
408:     min = hashTypeGetNextTimeToExpire(o);
409:     info->nextExpireTime = (min != EB_EXPIRE_TIME_INVALID) ? min : 0;
410: }
