412: /* Remove TTL from the field. */
413: static void listpackExPersist(robj *o, sds field, unsigned char *fptr,
414:                               unsigned char *vptr)
415: {
416:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
417: 
418:     unsigned char tmp[512];
419:     unsigned int slen;
420:     long long val;
421:     unsigned char *s;
422:     sds p = NULL;
423:     listpackEx *lpt = o->ptr;
424: 
425:     /* To persist a field, we have to delete it first and append to the end as
426:      * we want to maintain order by expiry time. Before deleting it, copy the
427:      * value if it is stored as string. */
428:     s = lpGetValue(vptr, &slen, &val);
429:     if (s) {
430:         /* Normally, item length in the listpack is limited by
431:          * 'hash-max-listpack-value' config. It is unlikely, but it might be
432:          * larger than sizeof(tmp). */
433:         if (slen > sizeof(tmp))
434:             p = sdsnewlen(s, slen);
435:         else
436:             memcpy(tmp, s, slen);
437:     }
438: 
439:     /* Delete field name, value and expiry time.  */
440:     lpt->lp = lpDeleteRangeWithEntry(lpt->lp, &fptr, 3);
441: 
442:     /* Append field to the end as it does not have expiry time. */
443:     lpt->lp = lpAppend(lpt->lp, (unsigned char*)field, sdslen(field));
444: 
445:     if (s)
446:         lpt->lp = lpAppend(lpt->lp, p ? (unsigned char*) p : tmp, slen);
447:     else
448:         lpt->lp = lpAppendInteger(lpt->lp, val);
449: 
450:     lpt->lp = lpAppendInteger(lpt->lp, HASH_LP_NO_TTL);
451: 
452:     sdsfree(p);
453: }
