455: /* If expiry time is changed, this function will place field into the correct
456:  * position. First, it deletes the field and re-inserts to the listpack ordered
457:  * by expiry time. */
458: static void listpackExUpdateExpiry(robj *o, sds field,
459:                                    unsigned char *fptr,
460:                                    unsigned char *vptr,
461:                                    uint64_t expireAt) {
462:     unsigned int slen;
463:     long long val;
464:     unsigned char tmp[512] = {0};
465:     unsigned char *valstr, *elem;
466:     listpackEx *lpt = o->ptr;
467:     sds tmpval = NULL;
468: 
469:     /* Copy value */
470:     valstr = lpGetValue(vptr, &slen, &val);
471:     if (valstr) {
472:         /* Normally, item length in the listpack is limited by
473:          * 'hash-max-listpack-value' config. It is unlikely, but it might be
474:          * larger than sizeof(tmp). */
475:         if (slen > sizeof(tmp))
476:             tmpval = sdsnewlen(valstr, slen);
477:         else
478:             memcpy(tmp, valstr, slen);
479:     }
480: 
481:     /* Delete field name, value and expiry time */
482:     lpt->lp = lpDeleteRangeWithEntry(lpt->lp, &fptr, 3);
483: 
484:     /* Insert to the listpack */
485:     fptr = lpFirst(lpt->lp);
486:     while (fptr) {
487:         long long currExpiry;
488: 
489:         elem = fptr; /* Keep a pointer to field name */
490:         fptr = lpNext(lpt->lp, fptr);
491:         serverAssert(fptr);
492:         fptr = lpNext(lpt->lp, fptr);
493:         serverAssert(fptr && lpGetIntegerValue(fptr, &currExpiry));
494: 
495:         if (currExpiry == HASH_LP_NO_TTL || (uint64_t) currExpiry >= expireAt) {
496:             /* Found a field with no expiry time or with a higher expiry time.
497:              * Insert new field just before it. */
498:             lpt->lp = lpInsertString(lpt->lp, (unsigned char*) field,
499:                                      sdslen(field), elem, LP_BEFORE, &fptr);
500: 
501:             /* Insert value after field name */
502:             if (valstr) {
503:                 lpt->lp = lpInsertString(lpt->lp,
504:                                          tmpval ? (unsigned char*) tmpval : tmp,
505:                                          slen, fptr, LP_AFTER, &fptr);
506:             } else {
507:                 lpt->lp = lpInsertInteger(lpt->lp, val, fptr, LP_AFTER, &fptr);
508:             }
509: 
510:             /* Insert expiry time after value. */
511:             lpt->lp = lpInsertInteger(lpt->lp, (long long) expireAt, fptr,
512:                                       LP_AFTER, NULL);
513:             goto out;
514:         }
515: 
516:         fptr = lpNext(lpt->lp, fptr);
517:     }
518: 
519:     /* Listpack is empty, append new item */
520:     lpt->lp = lpAppend(lpt->lp, (unsigned char*)field, sdslen(field));
521:     if (valstr)
522:         lpt->lp = lpAppend(lpt->lp, tmpval ? (unsigned char*) tmpval : tmp, slen);
523:     else
524:         lpt->lp = lpAppendInteger(lpt->lp, val);
525: 
526:     lpt->lp = lpAppendInteger(lpt->lp, (long long) expireAt);
527: 
528: out:
529:     sdsfree(tmpval);
530: }
