963:     /* Check if the field is too long for listpack, and convert before adding the item.
964:      * This is needed for HINCRBY* case since in other commands this is handled early by
965:      * hashTypeTryConversion, so this check will be a NOP. */
966:     if (isSetKeyValue && (o->encoding == OBJ_ENCODING_LISTPACK ||
967:                           o->encoding == OBJ_ENCODING_LISTPACK_EX))
968:     {
969:         if (sdslen(field) > server.hash_max_listpack_value ||
970:             sdslen(setKeyVal->value) > server.hash_max_listpack_value)
971:             hashTypeConvert(o, OBJ_ENCODING_HT, &db->hexpires);
972:     }
973: 
974:     if (o->encoding == OBJ_ENCODING_LISTPACK ||
975:         o->encoding == OBJ_ENCODING_LISTPACK_EX)
976:     {
977:         res = hashTypeSetExListpack(db, o, field, setKeyVal, expireAt, exInfo);
978:         goto SetExDone;
979:     } else if (o->encoding != OBJ_ENCODING_HT) {
980:         serverPanic("Unknown hash encoding");
981:     }
