649: /* Check the length of a number of objects to see if we need to convert a
650:  * listpack to a real hash. Note that we only check string encoded objects
651:  * as their string length can be queried in constant time. */
652: void hashTypeTryConversion(redisDb *db, robj *o, robj **argv, int start, int end) {
653:     int i;
654:     size_t sum = 0;
655: 
656:     if (o->encoding != OBJ_ENCODING_LISTPACK && o->encoding != OBJ_ENCODING_LISTPACK_EX)
657:         return;
658: 
659:     /* We guess that most of the values in the input are unique, so
660:      * if there are enough arguments we create a pre-sized hash, which
661:      * might over allocate memory if there are duplicates. */
662:     size_t new_fields = (end - start + 1) / 2;
663:     if (new_fields > server.hash_max_listpack_entries) {
664:         hashTypeConvert(o, OBJ_ENCODING_HT, &db->hexpires);
665:         dictExpand(o->ptr, new_fields);
666:         return;
667:     }
668: 
669:     for (i = start; i <= end; i++) {
670:         if (!sdsEncodedObject(argv[i]))
671:             continue;
672:         size_t len = sdslen(argv[i]->ptr);
673:         if (len > server.hash_max_listpack_value) {
674:             hashTypeConvert(o, OBJ_ENCODING_HT, &db->hexpires);
675:             return;
676:         }
677:         sum += len;
678:     }
679:     if (!lpSafeToAdd(hashTypeListpackGetLp(o), sum))
680:         hashTypeConvert(o, OBJ_ENCODING_HT, &db->hexpires);
681: }
