683: /* Get the value from a listpack encoded hash, identified by field.
684:  * Returns -1 when the field cannot be found. */
685: int hashTypeGetFromListpack(robj *o, sds field,
686:                             unsigned char **vstr,
687:                             unsigned int *vlen,
688:                             long long *vll)
689: {
690:     unsigned char *zl, *fptr = NULL, *vptr = NULL;
691: 
692:     if (o->encoding == OBJ_ENCODING_LISTPACK) {
693:         zl = o->ptr;
694:         fptr = lpFirst(zl);
695:         if (fptr != NULL) {
696:             fptr = lpFind(zl, fptr, (unsigned char*)field, sdslen(field), 1);
697:             if (fptr != NULL) {
698:                 /* Grab pointer to the value (fptr points to the field) */
699:                 vptr = lpNext(zl, fptr);
700:                 serverAssert(vptr != NULL);
701:             }
702:         }
703:     } else if (o->encoding == OBJ_ENCODING_LISTPACK_EX) {
704:         long long expire;
705:         unsigned char *h;
706:         listpackEx *lpt = o->ptr;
707: 
708:         fptr = lpFirst(lpt->lp);
709:         if (fptr != NULL) {
710:             fptr = lpFind(lpt->lp, fptr, (unsigned char*)field, sdslen(field), 2);
711:             if (fptr != NULL) {
712:                 vptr = lpNext(lpt->lp, fptr);
713:                 serverAssert(vptr != NULL);
714: 
715:                 h = lpNext(lpt->lp, vptr);
716:                 serverAssert(h && lpGetIntegerValue(h, &expire));
717: 
718:                 if (hashTypeIsExpired(o, expire))
719:                     return -1;
720:             }
721:         }
722:     } else {
723:         serverPanic("Unknown hash encoding: %d", o->encoding);
724:     }
725: 
726:     if (vptr != NULL) {
727:         *vstr = lpGetValue(vptr, vlen, vll);
728:         return 0;
729:     }
730: 
731:     return -1;
732: }
