820: /* Add a new field, overwrite the old with the new value if it already exists.
821:  * Return 0 on insert and 1 on update.
822:  *
823:  * By default, the key and value SDS strings are copied if needed, so the
824:  * caller retains ownership of the strings passed. However this behavior
825:  * can be effected by passing appropriate flags (possibly bitwise OR-ed):
826:  *
827:  * HASH_SET_TAKE_FIELD -- The SDS field ownership passes to the function.
828:  * HASH_SET_TAKE_VALUE -- The SDS value ownership passes to the function.
829:  *
830:  * When the flags are used the caller does not need to release the passed
831:  * SDS string(s). It's up to the function to use the string to create a new
832:  * entry or to free the SDS string before returning to the caller.
833:  *
834:  * HASH_SET_COPY corresponds to no flags passed, and means the default
835:  * semantics of copying the values if needed.
836:  *
837:  */
838: #define HASH_SET_TAKE_FIELD (1<<0)
839: #define HASH_SET_TAKE_VALUE (1<<1)
840: #define HASH_SET_COPY 0
841: int hashTypeSet(redisDb *db, robj *o, sds field, sds value, int flags) {
842:     HashTypeSet set = {value, flags};
843:     return (hashTypeSetEx(db, o, field, &set, 0, NULL) == HSET_UPDATE) ? 1 : 0;
844: }
