846: SetExRes hashTypeSetExpiry(HashTypeSetEx *ex, sds field, uint64_t expireAt, dictEntry **de) {
847:     dict *ht = ex->hashObj->ptr;
848:     dictEntry *newEntry = NULL, *existingEntry = NULL;
849: 
850:     /* New field with expiration metadata */
851:     hfield hfNew = hfieldNew(field, sdslen(field), 1 /*withExpireMeta*/);
852: 
853:     if ((ex->fieldSetCond == FIELD_DONT_CREATE) || (ex->fieldSetCond == FIELD_DONT_CREATE2)) {
854:         if ((existingEntry = dictFind(ht, field)) == NULL) {
855:             hfieldFree(hfNew);
856:             return (ex->fieldSetCond == FIELD_DONT_CREATE) ?
857:                    HSETEX_NO_CONDITION_MET : HSETEX_NO_FIELD;
858:         }
859:     } else {
860:         dictUseStoredKeyApi(ht, 1);
861:         newEntry = dictAddRaw(ht, hfNew, &existingEntry);
862:         dictUseStoredKeyApi(ht, 0);
863:     }
864: 
865:     if (newEntry) {
866:         *de = newEntry;
867: 
868:         if (ex->expireSetCond & (HFE_XX | HFE_LT | HFE_GT)) {
869:             dictDelete(ht, field);
870:             return HSETEX_NO_CONDITION_MET;
871:         }
872:     } else { /* field exist */
873:         *de = existingEntry;
874: 
875:         if (ex->fieldSetCond == FIELD_DONT_OVRWRT) {
876:             hfieldFree(hfNew);
877:             return HSETEX_NO_CONDITION_MET;
878:         }
879: 
880:         hfield hfOld = dictGetKey(existingEntry);
881: 
882:         /* If field doesn't have expiry metadata attached */
883:         if (!hfieldIsExpireAttached(hfOld)) {
884: 
885:             if (ex->expireSetCond & (HFE_XX | HFE_LT | HFE_GT)) {
886:                 hfieldFree(hfNew);
887:                 return HSETEX_NO_CONDITION_MET;
888:             }
889: 
890:             /* Delete old field. Below goanna dictSetKey(..,hfNew) */
891:             hfieldFree(hfOld);
892: 
893:         } else { /* field has ExpireMeta struct attached */
894: 
895:             /* No need for hfNew (Just modify expire-time of existing field) */
896:             hfieldFree(hfNew);
897: 
898:             uint64_t prevExpire = hfieldGetExpireTime(hfOld);
899: 
900:             /* If field has valid expiration time, then check GT|LT|NX */
901:             if (prevExpire != EB_EXPIRE_TIME_INVALID) {
902:                 if (((ex->expireSetCond == HFE_GT) && (prevExpire >= expireAt)) ||
903:                     ((ex->expireSetCond == HFE_LT) && (prevExpire <= expireAt)) ||
904:                     (ex->expireSetCond == HFE_NX) )
905:                     return HSETEX_NO_CONDITION_MET;
906: 
907:                 /* remove old expiry time from hash's private ebuckets */
908:                 dictExpireMetadata *dm = (dictExpireMetadata *) dictMetadata(ht);
909:                 ebRemove(&dm->hfe, &hashFieldExpireBucketsType, hfOld);
910: 
911:                 /* Track of minimum expiration time (only later update global HFE DS) */
912:                 if (ex->minExpireFields > prevExpire)
913:                     ex->minExpireFields = prevExpire;
914: 
915:             } else {
916:                 /* field has invalid expiry. No need to ebRemove() */
917: 
918:                 /* Check XX|LT|GT */
919:                 if (ex->expireSetCond & (HFE_XX | HFE_LT | HFE_GT))
920:                     return HSETEX_NO_CONDITION_MET;
921:             }
922: 
923:             /* Reuse hfOld as hfNew and rewrite its expiry with ebAdd() */
924:             hfNew = hfOld;
925:         }
926: 
927:         dictSetKey(ht, existingEntry, hfNew);
928:     }
929: 
930:     /* if expiration time is in the past */
931:     if (unlikely(checkAlreadyExpired(expireAt))) {
932:         hashTypeDelete(ex->hashObj, field);
933:         ex->fieldDeleted++;
934:         return HSETEX_DELETED;
935:     }
936: 
937:     if (ex->minExpireFields > expireAt)
938:         ex->minExpireFields = expireAt;
939: 
940:     dictExpireMetadata *dm = (dictExpireMetadata *) dictMetadata(ht);
941:     ebAdd(&dm->hfe, &hashFieldExpireBucketsType, hfNew, expireAt);
942:     ex->fieldUpdated++;
943:     return HSETEX_OK;
944: }
