431:  * This includes just the encoding byte, and the bytes needed to encode the length
432:  * of the element (excluding the element data itself)
433:  * If the element encoding is wrong then 0 is returned. */
434: static inline uint32_t lpCurrentEncodedSizeBytes(unsigned char *p) {
435:     if (LP_ENCODING_IS_7BIT_UINT(p[0])) return 1;
436:     if (LP_ENCODING_IS_6BIT_STR(p[0])) return 1;
437:     if (LP_ENCODING_IS_13BIT_INT(p[0])) return 1;
438:     if (LP_ENCODING_IS_16BIT_INT(p[0])) return 1;
439:     if (LP_ENCODING_IS_24BIT_INT(p[0])) return 1;
440:     if (LP_ENCODING_IS_32BIT_INT(p[0])) return 1;
441:     if (LP_ENCODING_IS_64BIT_INT(p[0])) return 1;
442:     if (LP_ENCODING_IS_12BIT_STR(p[0])) return 2;
443:     if (LP_ENCODING_IS_32BIT_STR(p[0])) return 5;
444:     if (p[0] == LP_EOF) return 1;
