448: /* Skip the current entry returning the next. It is invalid to call this
449:  * function if the current element is the EOF element at the end of the
450:  * listpack, however, while this function is used to implement lpNext(),
451:  * it does not return NULL when the EOF element is encountered. */
452: unsigned char *lpSkip(unsigned char *p) {
453:     unsigned long entrylen = lpCurrentEncodedSizeUnsafe(p);
454:     entrylen += lpEncodeBacklen(NULL,entrylen);
