1116:  *
1117:  * NOTE: The larger listpack is reallocated to contain the new merged listpack.
1118:  * Either 'first' or 'second' can be used for the result.  The parameter not
1119:  * used will be free'd and set to NULL.
1120:  *
1121:  * After calling this function, the input parameters are no longer valid since
1122:  * they are changed and free'd in-place.
1123:  *
1124:  * The result listpack is the contents of 'first' followed by 'second'.
1125:  *
1126:  * On failure: returns NULL if the merge is impossible.
1127:  * On success: returns the merged listpack (which is expanded version of either
1128:  * 'first' or 'second', also frees the other unused input listpack, and sets the
1129:  * input listpack argument equal to newly reallocated listpack return value. */
1130: unsigned char *lpMerge(unsigned char **first, unsigned char **second) {
1131:     /* If any params are null, we can't merge, so NULL. */
1132:     if (first == NULL || *first == NULL || second == NULL || *second == NULL)
1133:         return NULL;
1134: 
1135:     /* Can't merge same list into itself. */
1136:     if (*first == *second)
1137:         return NULL;
1138: 
1139:     size_t first_bytes = lpBytes(*first);
1140:     unsigned long first_len = lpLength(*first);
1141: 
1142:     size_t second_bytes = lpBytes(*second);
1143:     unsigned long second_len = lpLength(*second);
1144: 
1145:     int append;
1146:     unsigned char *source, *target;
1147:     size_t target_bytes, source_bytes;
1148:     /* Pick the largest listpack so we can resize easily in-place.
1149:      * We must also track if we are now appending or prepending to
1150:      * the target listpack. */
1151:     if (first_bytes >= second_bytes) {
1152:         /* retain first, append second to first. */
1153:         target = *first;
1154:         target_bytes = first_bytes;
1155:         source = *second;
1156:         source_bytes = second_bytes;
1157:         append = 1;
1158:     } else {
1159:         /* else, retain second, prepend first to second. */
1160:         target = *second;"}

